import os

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def base36_encode(n):
    s = []
    while n > 0:
        n, r = divmod(n, 36)
        s.append(BASE36[r])
    return "".join(reversed(s))

def base36_decode(s):
    n = 0
    for c in s:
        n = n * 36 + BASE36.index(c)
    return n

