    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ids.txt")
    with open(path) as f:
        lines = [line.strip() for line in f if line.strip()]
    last = lines[-1]
    print(next_id(last))

if __name__ == "__main__":
    main()

