import os

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
ID_LEN = 4


def next_id(current: str) -> str:
    """Return the next base-36 id after the given 4-character id."""
    num = 0
    for ch in current:
        num = num * 36 + BASE36.index(ch)

    num += 1

    result = ""
    for _ in range(ID_LEN):
        result = BASE36[num % 36] + result
        num //= 36

    return result


def main():
    ids_path = os.path.join(os.getcwd(), "ids.txt")
    last_id = None

    with open(ids_path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split("\t")
            if len(parts) >= 2 and parts[1].startswith("ORD-"):
                last_id = parts[1]

    if last_id is None:
        print("ORD-" + "0" * ID_LEN)
    else:
        suffix = last_id.split("-", 1)[1]
        print("ORD-" + next_id(suffix))


if __name__ == "__main__":
    main()

