import sys

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 32
CHAR_LEN = 4
PREFIX = "ORD-"


def decode(s: str) -> int:
    """Convert a 4-char string in the restricted alphabet to an integer."""
    value = 0
    for ch in s:
        value = value * BASE + ALPHABET.index(ch)
    return value


def encode(value: int) -> str:
    """Convert an integer to a 4-char string in the restricted alphabet."""
    chars = []
    for _ in range(CHAR_LEN):
        chars.append(ALPHABET[value % BASE])
